const clean = (v) => { const t = String(v == null ? '' : v).trim(); return /^\{[a-zA-Z0-9_]+\}$/.test(t) ? '' : t; };
const handle = clean(arg0).replace(/^@+/, '');
const cap = Math.max(1, Math.min(100, parseInt(clean(arg1), 10) || 20));
const compact = (o) => { for (const k of Object.keys(o)) { const v = o[k]; if (v == null || v === '' || (Array.isArray(v) && !v.length) || (typeof v === 'object' && !Array.isArray(v) && !Object.keys(v).length)) delete o[k]; } return o; };
const num = (s) => { const m = String(s == null ? '' : s).replace(/[,\s]/g, '').match(/\d+/); return m ? Number(m[0]) : null; };
const iso = (s) => { const d = s ? new Date(s) : null; return d && !isNaN(d) ? d.toISOString().replace('.000Z', 'Z') : null; };
const X = { name: 'X', id: 'x.com', url: 'https://x.com' };
const status = (sn, id) => 'https://x.com/' + sn + '/status/' + id;
const same = (a, b) => String(a || '').toLowerCase() === String(b || '').toLowerCase();
const screenName = (u) => u?.core?.screen_name || u?.legacy?.screen_name || '';
// The timeline batches the page itself downloaded (capture_responses). Every listed post is a
// `tweet_results.result` in them, in page order, so posts X dropped from the DOM while scrolling are kept.
const captured = (params && params.captured_responses) || { responses: [] };
const listed = new Map(), everyId = new Set();
const unwrap = (r) => (r && r.__typename === 'TweetWithVisibilityResults' ? r.tweet : r);
const walk = (root) => { const stack = [root]; while (stack.length) { const x = stack.pop(); if (!x || typeof x !== 'object') continue;
  if (Array.isArray(x)) { for (let i = x.length - 1; i >= 0; i--) stack.push(x[i]); continue; }
  const t = unwrap(x.tweet_results?.result);
  if (t?.legacy && t.rest_id && !x.promotedMetadata) { const id = String(t.rest_id); everyId.add(id); if (same(screenName(t.core?.user_results?.result), handle) && !t.legacy.retweeted_status_result) listed.set(id, t); }
  const keys = Object.keys(x); for (let i = keys.length - 1; i >= 0; i--) { const v = x[keys[i]]; if (v && typeof v === 'object') stack.push(v); } } };
for (const r of captured.responses || []) if (r && r.status >= 200 && r.status < 300 && r.json) walk(r.json);
// The page's own cards, read only for posts no captured response carried.
const dom = [];
for (const a of document.querySelectorAll("main article[data-testid='tweet'], main article")) {
  const link = a.querySelector("a[href*='/status/'] time")?.closest('a') || a.querySelector("a[href*='/status/']");
  const m = (link?.getAttribute('href') || '').match(/^\/([^/]+)\/status\/(\d+)/);
  if (!m || !same(m[1], handle) || everyId.has(m[2]) || dom.some((d) => d.id === m[2])) continue;
  const label = (sel) => a.querySelector(sel)?.getAttribute('aria-label') || '';
  dom.push({ id: m[2], screen_name: m[1],
    name: (a.querySelector("[data-testid='User-Name'] span")?.textContent || '').trim(),
    text: (a.querySelector("[data-testid='tweetText']")?.innerText || '').trim(),
    at: iso(a.querySelector('time')?.getAttribute('datetime')),
    counts: { likes: num(label("[data-testid='like'], [data-testid='unlike']")), reposts: num(label("[data-testid='retweet'], [data-testid='unretweet']")), replies: num(label("[data-testid='reply']")), views: num(label("a[href*='/analytics']")) } });
}
const entityText = (t) => {
  const note = t.note_tweet?.note_tweet_results?.result; const l = t.legacy || {}; let text, urls;
  const decode = (s) => String(s || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  if (note?.text) { text = decode(note.text); urls = note.entity_set?.urls || []; } else { text = Array.from(decode(l.full_text)).slice((l.display_text_range || [0])[0]).join(''); urls = l.entities?.urls || []; for (const m of l.extended_entities?.media || l.entities?.media || []) if (m.url) text = text.split(m.url).join(''); }
  for (const u of urls) if (u.url && u.expanded_url) text = text.split(u.url).join(u.expanded_url);
  return text.trim();
};
const party = (u, sn0) => { const sn = screenName(u) || sn0; return { name: u?.core?.name || u?.legacy?.name || sn, id: sn, url: 'https://x.com/' + sn }; };
const media = (l) => (l.extended_entities?.media || l.entities?.media || []).map((m) => compact({ kind: m.type === 'photo' ? 'image' : 'video', url: m.type === 'photo' ? m.media_url_https : ((m.video_info?.variants || []).filter((v) => /^video\//.test(v.content_type || '') && v.url).sort((a, b) => (b.bitrate || 0) - (a.bitrate || 0))[0]?.url || m.media_url_https), alt: m.ext_alt_text })).filter((m) => m.url);
const toPost = (t) => {
  const l = t.legacy || {}; const u = t.core?.user_results?.result; const article = t.article?.article_results?.result || null; const id = String(t.rest_id);
  const edits = t.edit_control?.edit_tweet_ids || t.edit_control?.edit_control_initial?.edit_tweet_ids;
  const q = unwrap(t.quoted_status_result?.result);
  return { id, user_id: l.user_id_str || u?.rest_id || '', author: party(u, handle),
    text: article ? String(article.plain_text || article.preview_text || '').trim() : entityText(t), title: article?.title || null,
    at: iso(l.created_at), conversation: l.conversation_id_str || id,
    reply_to: l.in_reply_to_status_id_str || null, reply_to_user: l.in_reply_to_user_id_str || null,
    lang: l.lang && l.lang !== 'und' ? l.lang : null, is_article: !!article,
    counts: compact({ likes: l.favorite_count, reposts: l.retweet_count, replies: l.reply_count, quotes: l.quote_count, bookmarks: l.bookmark_count, views: num(t.views?.count) }),
    edits: Array.isArray(edits) ? Math.max(0, edits.length - 1) : null, attachments: media(l),
    quoted: q?.legacy ? { id: String(q.rest_id || q.legacy.id_str), text: entityText(q), author: party(q.core?.user_results?.result, q.legacy.user_id_str) } : null };
};
const posts = [...listed.values()].slice(0, cap).map(toPost);
const byId = new Map(posts.map((p) => [p.id, p]));
const selfReply = (p) => !!(p.reply_to && p.reply_to_user && p.reply_to_user === p.user_id);
const startOf = (p) => { let cur = p; const guard = new Set([p.id]); while (selfReply(cur) && byId.has(cur.reply_to) && !guard.has(cur.reply_to)) { cur = byId.get(cur.reply_to); guard.add(cur.id); } return cur; };
const groups = new Map();
for (const p of posts) { const start = startOf(p); const key = selfReply(start) ? start.conversation : start.id; if (!groups.has(key)) groups.set(key, []); groups.get(key).push(p); }
const order = (a, b) => a.id.length - b.id.length || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
const items = [...groups.entries()].map(([key, group]) => {
  const ps = group.slice().sort(order); const first = ps.find((p) => p.id === key) || ps[0];
  const blocks = [], quoted = new Set();
  for (const p of ps) {
    blocks.push(compact({ id: p.id, kind: 'post', text: p.text, at: { order: blocks.length }, url: status(p.author.id, p.id), published_at: p.at === first.at ? null : p.at, attachments: p.attachments }));
    if (p.quoted && !quoted.has(p.quoted.id)) { quoted.add(p.quoted.id); blocks.push(compact({ id: 'q-' + p.quoted.id, kind: 'quoted', text: p.quoted.text, at: { order: blocks.length }, author: p.quoted.author, url: status(p.quoted.author.id, p.quoted.id) })); }
  }
  const broken = ps.some((p) => selfReply(startOf(p)));
  return compact({ type: 'rzn.item/v2', key: 'x:post:' + key, kind: 'post', url: status(first.author.id, key), title: first.title, author: first.author, published_at: first.at, published_in: X,
    marker: ps.every((p) => p.edits != null) ? 'edit:' + ps.reduce((n, p) => n + p.edits, 0) + ';posts:' + ps.length : null,
    fields: compact({ lang: first.lang, is_article: first.is_article, in_reply_to: first.reply_to && !selfReply(first) ? 'https://x.com/i/status/' + first.reply_to : null }),
    counts: first.counts, blocks,
    truncated: broken ? { reason: ps.some((p) => p.id === key) ? 'thread_gap' : 'thread_start_not_listed', returned_blocks: blocks.length } : null });
});
for (const b of dom.slice(0, Math.max(0, cap - posts.length))) {
  const url = status(b.screen_name, b.id);
  items.push(compact({ type: 'rzn.item/v2', key: 'x:post:' + b.id, kind: 'post', url, author: { name: b.name || b.screen_name, id: b.screen_name, url: 'https://x.com/' + b.screen_name }, published_at: b.at, published_in: X, counts: compact(b.counts),
    blocks: b.text ? [{ id: b.id, kind: 'post', text: b.text, at: { order: 0 }, url }] : [], truncated: { reason: 'post_detail_unavailable', returned_blocks: b.text ? 1 : 0 } }));
}
return { type: 'rzn.items/v2', items, next_cursor: null, listing: 'feed' };
